 * tarball named rather than dropped.
 *
 * `@async/witness` is not published anywhere: it is a `pnpm pack` tarball
 * committed under `vendor/`, which is what makes a fresh clone installable at
 * all. pnpm records it in the lockfile as `@async/witness@file:vendor/...`,
 * and a `file:` specifier is not a version — there is no registry coordinate to
 * ask OSV about, and `lockPackages` rightly refuses to invent one.
 *
 * So the entry is removed before the audit reads the lockfile, and it is
 * removed by name. Anything else carrying a non-registry protocol is left in
 * place and will still make `lockPackages` throw, which is the point: this
 * excuses exactly one declared vendored artifact and hides nothing else. What
 * the audit does not cover is stated where it belongs — `vendor/README.md`
 * records the artifact, its digest and its upstream commit, and
 * `packages/cli/src/witness/provenance.ts` re-hashes it on every check.
 */
const VENDORED_LOCK_COORDINATES: readonly string[] = Object.freeze([
	"'@async/witness@file:vendor/async-witness-0.8.0.tgz':",
]);

export function auditableLockText(lockText: string): string {
	return lockText
		.split('\n')
		.filter((line) => !VENDORED_LOCK_COORDINATES.includes(line.trim()))
		.join('\n');
}

