const fs=require("node:fs");
const sites=[
 ["react-memos","Memos","expectedProvenance"],
 ["react-papercups","Papercups","expectedProvenance"],
 ["react-boilerplate-zero-sw","React Boilerplate zero-SW","expectedProvenance"],
 ["angular-factoriolab","factoriolab","expectedProvenance"],
 ["react-boilerplate","React Boilerplate","expectedProvenance"],
 ["react-hospitalrun","HospitalRun","expectedProvenance"],
 ["next-killedbygoogle-v3-0-0","KilledByGoogle v3","expectedProvenance"],
 ["angular-jira-clone","jira-clone","expectedProvenance"],
 ["next-killedbygoogle","KilledByGoogle","provenance"],
 ["angular-tiny-translator","TinyTranslator","expectedProvenance"],
 ["react-linkfree","LinkFree","expectedProvenance"],
];
for (const [file,label,varName] of sites) {
  const p=`packages/cli/src/witness/${file}-run.ts`;
  let t=fs.readFileSync(p,"utf8");
  const lines=t.split("\n");
  const i=lines.findIndex((l)=>l.includes("canonicalize(receipt.provenance)"));
  if(i<0) throw new Error("no compare in "+p);
  if(!lines[i+1].includes("throw new Error(")) throw new Error("unexpected throw shape in "+p);
  lines.splice(i,2,`\tassertLinkedWitnessProvenanceEquivalent(receipt.provenance, ${varName}, ${JSON.stringify(label)});`);
  t=lines.join("\n");
  const before=t;
  t=t.replace(/import \{ verifyLinkedWitnessProvenance \} from '(\.\.?\/)*(witness\/)?provenance\.ts';/, (m)=>m.replace("{ verifyLinkedWitnessProvenance }","{\n\tassertLinkedWitnessProvenanceEquivalent,\n\tverifyLinkedWitnessProvenance,\n}"));
  if(t===before) throw new Error("import not rewritten in "+p);
  fs.writeFileSync(p,t);
  console.log("patched",p);
}
'

