	if (!options.rootDir)
		throw new Error(
			`Digesting ${entry.name} requires the repository root: a ${FILE_PROTOCOL} coordinate is only auditable with its tarball digest`,
		);
	return {
		name: entry.name,
		version,
		kind: 'file',
		tarball,
		sha256: sha256(readFileSync(path.join(options.rootDir, tarball))),
	};
}

